package com.eidolon.sc.mobile;

import java.util.*;import java.security.MessageDigest;import org.json.*;

/** Bounded conversation intentions inside the existing role life document. No timers or model calls. */
final class ExchangeIntent {
 static final int MAX=6,RECEIPTS=32;static final long DAY=86400000L;
 static String hash(String text){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(text.getBytes("UTF-8"));StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 static JSONObject desk(JSONObject state)throws Exception{JSONObject d=state.optJSONObject("communication");if(d==null){d=new JSONObject().put("items",new JSONArray()).put("receipts",new JSONArray());state.put("communication",d);}return d;}
 static JSONObject item(String family,String id,String version,String title,JSONObject evidence,long at,long until,int priority)throws Exception{
  evidence=new JSONObject(evidence.toString());evidence.remove("journey");evidence.remove("steps");
  return new JSONObject().put("key",hash(family+"/"+id+"/"+version)).put("family",family).put("sourceId",id).put("sourceVersion",version).put("title",MediaData.cut(title,180)).put("evidence",evidence).put("formedAt",at).put("changedAt",at).put("expires",until).put("priority",priority).put("status","ready").put("reason","");
 }
 static JSONArray candidates(JSONObject frame,JSONObject basis,List<ChatStore.Message> history,long now,boolean eventOnly)throws Exception{
  JSONArray out=new JSONArray(),callbacks=frame.optJSONArray("callbacks"),goals=frame.optJSONArray("goals");
  if(callbacks!=null)for(int i=0;i<callbacks.length();i++){JSONObject e=callbacks.getJSONObject(i);if(!e.optString("exchangeStatus").equals("tried")||e.optBoolean("alreadyShared"))continue;long at=e.optLong("trialAt");if(at<=0||at>now||now-at>3*DAY)continue;out.put(item("callback",e.getString("id"),e.optLong("version")+"",e.optString("result","虚拟尝试有了记录"),e,at,at+3*DAY,90));}
  if(goals!=null)for(int i=0;i<goals.length();i++){JSONObject g=goals.getJSONObject(i);long at=g.optLong("lastProgressAt");if(!g.optBoolean("unsharedProgress")||g.optString("progressKey").equals(g.optString("offeredProgressKey"))||at<=0||at>now||now-at>3*DAY)continue;out.put(item("goal",g.getString("id"),g.optString("progressKey"),g.optString("title"),g,at,at+3*DAY,80));}
  JSONArray events=basis.optJSONArray("events");if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);String phase=e.optString("conversationStatus");if(e.optBoolean("alreadyAsked")||e.optBoolean("alreadyExpressed")||!Arrays.asList("completed","inferred_completed","elapsed_result_unknown").contains(phase))continue;long at=e.optLong("actualAt",e.optLong("expectedEnd"));if(at<=0)at=e.optLong("expectedStart");if(at<=0||at>now||now-at>3*DAY)continue;
   // Goal/callback progress is the same event, not a second independent reason to contact.
   boolean linked=false;for(int j=0;goals!=null&&j<goals.length();j++){String id=goals.getJSONObject(j).optString("id");if(!id.isEmpty()&&(id.equals(e.optString("goalId"))||e.optString("id").startsWith(id+"/")))linked=true;}if(linked)continue;
   out.put(item("event",e.getString("id"),e.optString("viewVersion"),e.optString("title"),e,at,at+3*DAY,60));
  }
  if(!eventOnly){ChatStore.Message user=null,last=null;for(ChatStore.Message m:history){if(m.id<=0||m.sentAt>now)continue;last=m;if(m.role.equals("user"))user=m;}
   // A recent shared exchange can support one greeting. Absence and a new calendar day never create another.
   if(user!=null&&last!=null&&last.role.equals("assistant")&&now-user.sentAt<DAY&&now-user.sentAt>=30*60000L&&!user.text.matches("(?s).*(别再|不要再|不用回|先别联系|不想聊|勿扰).*")){
    JSONObject e=new JSONObject().put("sourceMessageId",user.id).put("at",user.sentAt).put("text",MediaData.cut(user.text,300)).put("boundary","ordinary_greeting_or_affection_no_pressure_no_invented_update");
    out.put(item("greeting","user/"+user.id,"1","最近交流后的自然问候或亲近表达",e,user.sentAt,user.sentAt+DAY,10));
   }
  }
  return out;
 }
 static JSONObject reconcile(JSONObject state,JSONObject frame,JSONObject basis,List<ChatStore.Message> history,long now,boolean eventOnly)throws Exception{
  JSONObject d=desk(state);JSONArray cached=d.getJSONArray("receipts");for(int i=cached.length()-1;i>=0;i--)if(cached.getJSONObject(i).optLong("expires",Long.MAX_VALUE)<=now)cached.remove(i);JSONArray sources=candidates(frame,basis,history,now,eventOnly),items=d.getJSONArray("items"),receipts=d.getJSONArray("receipts");Set<String> active=new HashSet<>();for(int i=sources.length()-1;i>=0;i--){JSONObject candidate=sources.getJSONObject(i);if(candidate.optString("family").equals("greeting")&&candidate.getJSONObject("evidence").optLong("sourceMessageId")<=d.optLong("restoredUserFloor"))sources.remove(i);}
  for(int i=0;i<sources.length();i++)active.add(sources.getJSONObject(i).getString("key"));
  for(int i=0;i<items.length();i++){JSONObject e=items.getJSONObject(i);if((!active.contains(e.getString("key"))&&!e.optString("family").equals("occasion"))||now>=e.getLong("expires")){if(Arrays.asList("ready","waiting","attempted").contains(e.optString("status")))e.put("status","dropped").put("reason","来源已变化、已交流或适用期已过");}}
  List<JSONObject> ranked=new ArrayList<>();for(int i=0;i<sources.length();i++){JSONObject source=sources.getJSONObject(i);JSONObject prior=byKey(items,source.getString("key"));boolean seen=false;for(int r=0;r<receipts.length();r++)if(receipts.getJSONObject(r).getString("key").equals(source.getString("key")))seen=true;if((seen||receipts.length()>=RECEIPTS)&&prior==null)continue;ranked.add(prior==null?source:prior);}
  for(int i=0;i<items.length();i++){JSONObject e=items.getJSONObject(i);if(e.optString("family").equals("occasion")&&now<e.optLong("expires"))ranked.add(e);}
  ranked.sort((a,b)->Integer.compare(b.optInt("priority"),a.optInt("priority")));JSONArray next=new JSONArray();for(int i=0;i<Math.min(MAX,ranked.size());i++)next.put(ranked.get(i));
  // Terminal keys survive item eviction so another entry cannot re-request the same unchanged source.
  for(int i=0;i<items.length();i++){JSONObject e=items.getJSONObject(i);if(!Arrays.asList("ready","waiting").contains(e.optString("status")))remember(d,e,e.optString("status"),now);}
  d.put("items",next);JSONObject chosen=null;long lastUser=0,lastUserAt=0;String userText="";for(ChatStore.Message m:history)if(m.role.equals("user")&&m.id>lastUser){lastUser=m.id;lastUserAt=m.sentAt;userText=m.text;}
  for(int i=0;i<next.length();i++){JSONObject e=next.getJSONObject(i);long sourceUser=e.getJSONObject("evidence").optLong("lastSourceMessageId",e.getJSONObject("evidence").optLong("sourceMessageId"));
   if(lastUserAt>e.optLong("changedAt")&&lastUser>sourceUser&&lastUser>e.optLong("observedUser")&&related(userText,e)&&!e.optString("family").equals("greeting")){e.put("status","merged").put("reason","用户已在聊天中接起此事，留给当前回复").put("observedUser",lastUser);remember(d,e,"merged",now);}
   if(chosen==null&&receipts.length()<RECEIPTS&&e.optString("status").equals("ready"))chosen=e;
  }
  JSONObject result=new JSONObject().put("schema",1).put("character",state.getString("character")).put("decision",chosen==null?"wait":"evaluate").put("reason",chosen==null?"没有尚未交流且适用的具体内容":"有来源的待表达事项").put("selected",chosen==null?JSONObject.NULL:new JSONObject(chosen.toString())).put("lastUserId",lastUser).put("memoryEpoch",frame.optLong("baseMemoryEpoch")).put("planRevision",basis.optString("planRevision")).put("currentActivity",basis.opt("currentActivity")).put("now",now).put("additionalRequests",0);
  d.put("checkedKey",hash(active.toString()+"/"+lastUser+"/"+frame.optLong("baseMemoryEpoch")));return result;
 }
 static JSONObject byKey(JSONArray a,String key){if(a==null)return null;for(int i=0;i<a.length();i++)if(a.optJSONObject(i)!=null&&a.optJSONObject(i).optString("key").equals(key))return a.optJSONObject(i);return null;}
 static boolean related(String text,JSONObject item){String title=item.optString("title");if(title.length()>=4&&text.contains(title))return true;JSONObject e=item.optJSONObject("evidence");if(e==null)return false;String words=title+" "+e.optString("advice")+" "+e.optString("result")+" "+e.optString("title");String clean=text.replaceAll("[\\p{P}\\p{Z}\\s]","");for(int i=0;i+4<=clean.length();i++)if(words.contains(clean.substring(i,i+4)))return true;return false;}
 static void remember(JSONObject d,JSONObject item,String status,long now)throws Exception{JSONArray a=d.getJSONArray("receipts");JSONObject old=byKey(a,item.getString("key"));if(old==null){if(a.length()>=RECEIPTS)return;old=new JSONObject().put("key",item.getString("key"));a.put(old);}old.put("status",status).put("at",now).put("expires",item.optLong("expires",now+3*DAY));if(a.length()>RECEIPTS)throw new Exception("交流依据缓存已满，等待旧事项失效");}
 static boolean claim(JSONObject state,JSONObject frame,String channel,long now)throws Exception{JSONObject selected=frame.optJSONObject("selected");if(selected==null)return false;JSONObject d=desk(state),item=byKey(d.getJSONArray("items"),selected.optString("key"));if(d.getJSONArray("receipts").length()>=RECEIPTS||item==null||!item.optString("status").equals("ready")||byKey(d.getJSONArray("receipts"),selected.optString("key"))!=null||now>=item.optLong("expires"))return false;item.put("status","attempted").put("reason","本次已领取；未知结果不自动重试").put("channel",channel).put("attemptAt",now);remember(d,item,"attempted",now);frame.put("channel",channel);return true;}
 static String guard(JSONObject frame,JSONObject state,long lastUser,long epoch,JSONObject temporal,long now)throws Exception{
  if(frame==null)return "";if(state==null||!frame.optString("character").equals(state.optString("character")))return "交流事项的角色归属不一致";JSONObject selected=frame.optJSONObject("selected");if(selected==null)return "缺少待表达依据";JSONObject d=state==null?null:state.optJSONObject("communication"),item=d==null?null:byKey(d.optJSONArray("items"),selected.optString("key"));
  if(now<frame.optLong("now"))return "设备时间已回退，原候选时间不可靠";if(lastUser!=frame.optLong("lastUserId"))return "用户已补充消息，旧主动内容不再投放";if(epoch!=frame.optLong("memoryEpoch"))return "用户理解已更新";if(now>=selected.optLong("expires"))return "待表达内容已过适用期";
  if(item==null||!item.optString("status").equals("attempted"))return "该事项已在其他入口处理或放弃";
  if(temporal!=null&&(!frame.optString("planRevision").equals(temporal.optString("planRevision"))||!ReplyBasis.activityKey(frame.optJSONObject("currentActivity")).equals(ReplyBasis.activityKey(temporal.optJSONObject("planned_activity")))))return "日程或活动窗口已变化，旧主动内容已放弃";
  String family=selected.optString("family"),id=selected.optString("sourceId");if(!state.optBoolean("enabled")&&Arrays.asList("goal","callback").contains(family))return "生活连续性已关闭";JSONObject actual=LifeData.find(state.optJSONArray(family.equals("goal")?"goals":"events"),id);
  if(!family.equals("greeting")){if(actual==null||actual.optBoolean("sourceMissing"))return "事项来源已失效";if(family.equals("goal")&&!ContinuityContext.progressKey(actual).equals(selected.optString("sourceVersion"))||family.equals("callback")&&!String.valueOf(ContinuityLife.version(actual)).equals(selected.optString("sourceVersion"))||family.equals("event")&&!selected.optString("sourceVersion").startsWith(actual.optLong("eventVersion",1)+"/"))return "事项已有新进展或纠正";}
  return "";
 }
 static JSONObject json(String raw)throws Exception{String s=raw.trim();if(s.startsWith("```")){int at=s.indexOf('\n');if(at>0&&s.endsWith("```"))s=s.substring(at+1,s.length()-3).trim();}return s.startsWith("{")?new JSONObject(s):null;}
 static String decision(String raw)throws Exception{JSONObject j=json(raw),e=j==null?null:j.optJSONObject("exchange");String decision=e==null?"say":e.optString("decision","say");if(!Arrays.asList("say","wait","drop").contains(decision))throw new Exception("主动交流决定无效");if(!decision.equals("say")&&j.optJSONArray("messages")!=null&&j.getJSONArray("messages").length()>0)throw new Exception("等待或放弃不能同时携带待发送正文");return decision;}
 static void finish(JSONObject state,JSONObject frame,String status,long now)throws Exception{JSONObject selected=frame==null?null:frame.optJSONObject("selected");if(selected==null)return;JSONObject d=desk(state),e=byKey(d.getJSONArray("items"),selected.optString("key"));if(e!=null&&e.optString("status").equals("attempted")){e.put("status",status).put("reason",status.equals("waiting")?"角色选择等待；无新依据不重试":"本次表达已结束");remember(d,e,status,now);}}
 static boolean delivered(JSONObject state,JSONObject effect,String answer,long id,long now)throws Exception{
  if(effect==null)return false;JSONObject frame=effect.optJSONObject("exchangeFrame");JSONObject d=desk(state);boolean changed=false;
  if(frame!=null){JSONObject selected=frame.optJSONObject("selected"),e=selected==null?null:byKey(d.getJSONArray("items"),selected.optString("key"));if(e!=null&&e.optString("status").equals("attempted")){boolean covered=effect.optBoolean("exchangeCovered")||related(answer,e)||e.optString("family").equals("greeting");e.put("status",covered?"delivered":"offered").put("deliveredRef",id).put("deliveredAt",now).put("reason",covered?"实际送达并有正文依据":"已投放但未确认讲出该信息，不自动重试");remember(d,e,e.getString("status"),now);changed=true;}}
  // A normal delivered reply can merge an outstanding item without banning later user-requested recall.
  JSONArray a=d.getJSONArray("items");for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i);if(Arrays.asList("ready","waiting","attempted","merged","offered").contains(e.optString("status"))&&related(answer,e)){e.put("status","delivered").put("deliveredRef",id).put("deliveredAt",now).put("reason","已随实际回复交流");remember(d,e,"delivered",now);changed=true;}}
  return changed;
 }
 static boolean covered(String raw,String answer,JSONObject frame)throws Exception{JSONObject j=json(raw),e=j==null?null:j.optJSONObject("exchange"),selected=frame.optJSONObject("selected");if(e==null||selected==null)return false;String quote=e.optString("quote");return e.optString("key").equals(selected.optString("key"))&&quote.length()>=2&&quote.length()<=500&&answer.contains(quote)&&related(quote,selected);}
 static void attach(JSONObject request,JSONObject frame,boolean letter)throws Exception{JSONObject system=request.getJSONArray("messages").getJSONObject(0);system.put("content",system.getString("content")+"\nBEGIN_EIDOLON_EXCHANGE\n"+frame+"\nEND_EIDOLON_EXCHANGE\n本次只是交流评估，不要求填满时间窗口或数量。selected是唯一有依据的待表达事项，按evidence区分用户材料、虚拟进展、实际尝试和结果未知；不能虚构外部操作。可以说、等待或放弃。使用同一个eidolon_chat JSON协议，顶层附exchange:{decision:say/wait/drop,key:selected.key,quote:本次正文中确实讲到该事项的原句}。wait/drop时messages:[]，没有其他效果；无需编造台词。say时"+(letter?"messages为1条含完整称呼/正文/落款的ja和zh纯文本信件":"沿用本次聊天messages协议")+"。不因没有回复而催促，不每次加问题，不显示内部字段。兼容旧服务直接返回台词，但无法确认分享的内容不会记成已经讲过。只能声称虚拟活动；现实工具须有真正执行成功依据。");}
 static void validate(JSONObject state)throws Exception{JSONObject d=state.optJSONObject("communication");if(d==null)return;JSONArray a=d.getJSONArray("items"),r=d.getJSONArray("receipts");if(a.length()>MAX||r.length()>RECEIPTS||d.toString().length()>30000)throw new Exception("待表达记录过多");Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i);if(!seen.add(e.getString("key"))||!e.getString("key").matches("[a-f0-9]{64}")||!Arrays.asList("ready","waiting","attempted","merged","dropped","delivered","offered").contains(e.getString("status"))||!Arrays.asList("goal","callback","event","greeting","occasion").contains(e.getString("family"))||e.getString("title").length()>180||e.getLong("formedAt")<0||e.getLong("expires")<e.getLong("formedAt"))throw new Exception("待表达记录无效");}for(int i=0;i<r.length();i++)if(!r.getJSONObject(i).getString("key").matches("[a-f0-9]{64}")||r.getJSONObject(i).optString("status").length()>20)throw new Exception("交流记录无效");}
 private ExchangeIntent(){}
}
